// Native iOS hierarchy from main 34557847, with local illustrative state.
const glyph=name=>'<svg aria-hidden="true"><use href="/assets/parent-icons.svg#'+name+'"></use></svg>';
const row=(label,value,action='')=>'<'+(action?'button type="button" data-parent-action="'+action+'"':'div')+' class="ios-row"><span>'+label+'</span><span>'+value+'<i>⌄</i></span></'+(action?'button':'div')+'>';
const group=(title,body,target='')=>'<div class="ios-group"'+(target?' data-parent-target="'+target+'"':'')+'><p class="ios-section-label">'+title+'</p><div class="ios-inset">'+body+'</div></div>';
export const initialParentState=()=>({child:0,range:0,detail:false,deleted:false,confirm:false,moment:false,speed:1,style:0,topics:{},prepared:false,notice:''});
export const parentChapters = [
  {id:'today', label:'Today', tab:0, title:'A clear view.\nOf their day.', summary:'Choose a child. Choose a time window. See the activities that have been saved.', why:'The child selector stays close to the information it controls. Date ranges and the last successful update make the numbers interpretable: whose activity, over which period, and how fresh it is. The native app also clears the old child’s state when switching profiles, so a delayed response cannot quietly show the wrong child’s information.', limit:'These are activity counts, not scores or proof of learning. Offline discovery listening is not included. An update time is not a claim of continuous monitoring.'},
  {id:'together', label:'Together', tab:0, title:'A small moment.\nBack to you.', summary:'A recent discovery becomes an invitation to talk, notice, or try something together.', why:'“A moment together” is grounded in a saved activity. Its “Why this suggestion?” view makes that connection explicit. Inviting a child to explain an idea in their own words can help a parent hear what made sense and where a little support would be useful. The design brings the experience back into a human relationship.', limit:'A conversation starter is not an assessment of ability, a diagnosis, or an inference about your child’s personality.'},
  {id:'activity', label:'Activity', tab:1, title:'See the exchange.\nKeep the context.', summary:'Review saved questions and answers. See when a safeguard shaped a response. Delete an individual activity.', why:'A summary can be useful; the underlying exchange gives it meaning. Activity filters help a parent find Ask, Math, Stories, or safeguard interventions. Details can include the original question, answer, supported versus independent Math practice, and a recorded policy reason. Deletion asks for confirmation and should only leave the detail screen after it succeeds.', limit:'Reports cover saved events, not every offline experience. A safeguard notice describes an intervention; it is not an emergency alert or a promise that everything was detected.'},
  {id:'topics', label:'Topics', tab:2, title:'Your family.\nYour guidance.', summary:'Choose an age-appropriate explanation, a grown-up conversation, or no discussion for supported topics.', why:'Readiness and family values are contextual. The current iOS source has preferences for religion, violence, non-explicit body development, drugs and alcohol, clean profanity explanations, politics and civics, and money and product literacy. Each choice is named by its consequence. Essential protections remain separate, so a preference cannot authorize harmful instructions, exploitation, or commercial persuasion.', limit:'Expanded controls depend on service support and still require release validation. Questions about being hurt or feeling unsafe must retain supportive guidance toward a trusted adult.'},
  {id:'reading', label:'Reading', tab:2, title:'Set a pace.\nLet the story breathe.', summary:'Hear a reading-speed sample before sending your choice to the paired Watch.', why:'The parent can listen before deciding. Calm is the starting speed. The native app distinguishes “Saved here. Waiting for the paired Watch.” from “Applied on the paired Watch.” That difference matters: a tap on the phone is not proof that a device has received a setting. Downloaded books remain available offline; they do not require daily reapproval.', limit:'This website tour does not send settings to a device. Its separate interactive audio preview uses prepared recordings.'},
  {id:'guidance', label:'Guidance', tab:2, title:'A useful foothold.\nRoom to grow.', summary:'Set the starting math level and choose a supported explanation style.', why:'A starting level is a place to begin, not a permanent label. The current source includes age and starting Math controls, with difficulty adapting as practice continues. Bounded guidance choices—shorter sentences, familiar everyday examples, or avoiding scary imagery—make the requested support understandable. Existing progress is preserved rather than reset to a new-profile default.', limit:'TrustinJr initially focuses on ages 4–5. Wider age choices in development source are not an announcement of broader release support. Illustrated books keep their fixed wording; no learning gains are promised.'},
  {id:'setup', label:'Watch setup', tab:3, title:'Connected.\nOn your terms.', summary:'Choose a child, prepare the connection, and send it to the paired Watch.', why:'Setup separates a parent account, a child profile, and a Watch’s access. The device list states access expiry instead of pretending the Watch is currently online. Disconnect asks for confirmation and explains its scope: it stops future server access, without unpairing Apple devices or deleting the parent account. Watch-face customization remains an optional destination.', limit:'The current beta requires a Watch normally paired with this iPhone. Apple Family Setup is not supported in this beta. Master Guardian sharing is a separate, unfinished account-design direction and is not presented as available here.'}
];


export function parentScreen(id='today',s=initialParentState()){
  let title='Trustin Jr.',body='',tab=0;
  const child=['Explorer','Adventurer'][s.child],range=['Today','This week'][s.range];
  const activity='<button class="ios-activity" data-parent-action="detail"><div><b>Curiosity</b><span>9:35 AM</span></div><strong>Why does the Moon change shape?</strong><p>We see different parts of the Moon lit by the Sun.</p></button>';
  if(['overview','today','together'].includes(id)){
    body='<div class="ios-title"><h3>Today</h3><img src="/assets/trustin.png" width="300" height="353" alt=""></div><div data-parent-target="today">'+row('Child',child,'child')+row('Date range',range,'range')+'<p class="ios-caption">Updated 9:41 AM · iPhone time</p></div><div class="ios-metrics"><div><strong>'+(s.child?1:s.range?6:2)+'</strong><span>Questions</span></div><div><strong>'+(s.range?3:1)+'</strong><span>Math missions</span></div><div><strong>'+(s.range?2:1)+'</strong><span>Stories</span></div></div><p class="ios-caption">Saved activities · '+range+'</p><div class="ios-moment" data-parent-target="together"><strong>'+glyph('heart')+' A moment together</strong><p>Ask '+child+' what they noticed about the Moon.</p><button data-parent-action="moment" aria-expanded="'+s.moment+'">Why this suggestion?</button>'+(s.moment?'<p class="ios-caption">Inspired by their saved question about the Moon’s changing shape.</p>':'')+'</div><div class="ios-row ios-recent"><strong>Recent activity</strong><button data-parent-action="activity">View all</button></div>'+(s.deleted?'<p>No saved activity in this preview.</p>':activity);
  }else if(id==='activity'){
    title='Activity';tab=1;
    if(s.deleted)body='<p class="ios-caption">No saved activity.</p><button class="ios-native-action" data-parent-action="restore">Restore sample</button>';
    else if(!s.detail)body='<div data-parent-target="activity"><h3 class="ios-detail-title">Activity report</h3><p class="ios-caption">'+child+' · '+range+'</p>'+activity+'</div>';
    else body='<button class="ios-back" data-parent-action="back">‹ Activity report</button><div data-parent-target="activity"><h3 class="ios-detail-title">Why does the Moon change shape?</h3><p class="ios-caption">Today at 9:35 AM</p><h4>Question</h4><p>Why does the Moon change shape?</p><h4>Trustin’s answer</h4><p>The Moon stays round like a ball. As it travels around Earth, we see different parts of its sunlit side.</p>'+(s.confirm?'<div class="ios-confirm"><p>Delete this activity?</p><button data-parent-action="cancelDelete">Keep</button><button data-parent-action="delete">Delete</button></div>':'<button class="ios-delete" data-parent-action="confirmDelete">Delete this activity</button>')+'</div>';
  }else if(id==='topics'){
    title='Safeguards';tab=2;
    const names=['Religion','Violence','Body development','Drugs and alcohol','Profanity','Politics and civics','Money and products'];
    const values=['Ask a grown-up','Block discussion','Age-appropriate'];
    body=group('Child',row('Child',child,'child'))+group('Topic preferences',names.map((name,i)=>row(name,values[s.topics[i]??(i===1?1:i===4||i===6?2:0)],'topic-'+i)).join(''),'topics')+group('Always protected','<p>'+glyph('shield')+' Essential protections remain in place.</p><p class="ios-caption">No harmful instructions, exploitation or commercial persuasion. Help-seeking remains supported.</p>')+'<button class="ios-native-action" data-parent-action="save">Save safeguards</button><div class="ios-section-links"><button data-parent-action="reading">Story reading ›</button><button data-parent-action="guidance">Your guidance ›</button></div>';
  }else if(id==='reading'){
    title='Safeguards';tab=2;
    body=group('Story reading','<p>Reading speed</p><div class="ios-speed">'+['Slower','Calm','Natural'].map((v,i)=>'<button data-parent-action="speed-'+i+'" aria-pressed="'+(s.speed===i)+'">'+v+'</button>').join('')+'</div><div class="ios-row ios-native-action"><button data-parent-action="sample">Hear sample</button><button data-parent-action="send">Send to Watch</button></div><p class="ios-caption">Calm is the starting speed. Downloaded books work offline.</p>','reading')+group('Learning pace',row('Age','4–5')+row('Starting math level','Kindergarten')+'<p class="ios-caption">Difficulty adapts as your child practices.</p>')+'<button class="ios-native-action" data-parent-action="topics">Topic preferences ›</button>';
  }else if(id==='guidance'){
    title='Safeguards';tab=2;
    body=group('Learning pace',row('Age','4–5')+row('Starting math level','Kindergarten')+'<p class="ios-caption">A starting point, with room to grow.</p>')+group('Your guidance',row('Explanation style',['Familiar everyday examples','Shorter sentences','Avoid scary imagery'][s.style],'style'),'guidance')+'<button class="ios-native-action" data-parent-action="save">Save safeguards</button>'+group('Always protected','<p>'+glyph('shield')+' Essential protections stay in place.</p>')+'<button class="ios-native-action" data-parent-action="topics">Topic preferences ›</button>';
  }else if(id==='setup'){
    title='Watch setup';tab=3;
    body=group('1 · Choose a child',row('Child',child,'child')+'<button class="ios-native-action" data-parent-action="prepare">Prepare connection</button>')+group('2 · Connect Watch','<p>'+(s.prepared?'Ready for the paired Watch. Keep both apps open.':'On the Watch, open Trustin Jr. → gear. Keep both apps open.')+'</p><button class="ios-native-action" data-parent-action="send">Send to Watch</button>','setup')+group('Watches','<p>No Watch connected yet.</p>')+'<p class="ios-caption">Requires a Watch paired with this iPhone. Family Setup is not supported in this beta.</p>';
  }
  const tabs=[['sun','Today','today'],['clock','Activity','activity'],['shield','Safeguards','topics'],['watch','Watch setup','setup']];
  return '<div class="ios-status"><span>9:41</span><span class="ios-island"></span><span>▰</span></div><div class="ios-nav-title">'+title+'</div><div class="ios-scroll" tabindex="0" aria-label="'+title+' sample content">'+body+(s.notice?'<p class="ios-caption ios-notice" role="status">'+s.notice+'</p>':'')+'</div><div class="ios-tabs" role="group" aria-label="Parent app navigation">'+tabs.map(([icon,label,key],i)=>'<button data-parent-action="'+key+'" '+(tab===i?'class="ios-selected" aria-pressed="true"':'aria-pressed="false"')+'>'+glyph(icon)+'<span>'+label+'</span></button>').join('')+'</div><div class="ios-home-bar"></div>';
}
